#!/usr/bin/env bash
set -Eeuo pipefail
SELF="$(readlink -f "$0" 2>/dev/null || printf %s "$0")"
TMP="$(mktemp -d /tmp/vpn-server-master.XXXXXX)"
trap 'rm -rf "$TMP"' EXIT
PAYLOAD_START=$(awk '/^__PAYLOAD_BELOW__$/{print NR+1; exit}' "$SELF")
tail -n +"$PAYLOAD_START" "$SELF" | base64 -d | gzip -d > "$TMP/vpn-server-master.real.sh"
chmod 700 "$TMP/vpn-server-master.real.sh"
exec bash "$TMP/vpn-server-master.real.sh" "$@"
__PAYLOAD_BELOW__

